{"description":"Check BsaI motifs in full amplicons","cmd":"python3 - <<'PY'
import subprocess
seqs={}; name=None
for line in open('sequences.fasta'):
    line=line.strip()
    if not line: continue
    if line.startswith('>'):
        name=line[1:].split()[0]; seqs[name]=''
    else: seqs[name]+=line.upper()
def rc(s):
    tr=str.maketrans('ACGT','TGCA'); return s.translate(tr)[::-1]

X='T'
blocks={'backbone':seqs['input'][690:]+seqs['input'][:210],
        'egfp':seqs['egfp'][0:714],
        'flag':seqs['flag'][3:87],
        'snap':seqs['snap'][3:549]}
fwd_L={'backbone':25,'egfp':18,'flag':18,'snap':22}
rev_L={'backbone':45,'egfp':20,'flag':22,'snap':18}
order=['backbone','egfp','flag','snap']
for name in order:
    blk=blocks[name]; Lf=fwd_L[name]; Lr=rev_L[name]
    nxt=order[(order.index(name)+1)%4]
    fwd_primer='GGTCTC'+X+blk[:Lf]
    rev_primer='GGTCTC'+X+rc(blocks[nxt][:4])+rc(blk[-Lr:])
    amp=fwd_primer+blk[Lf:len(blk)-Lr]+rc(rev_primer)
    print('###',name)
    for motif in ['GGTCTC','GAGACC']:
        positions=[]
        i=0
        while True:
            i=amp.find(motif,i)
            if i<0: break
            positions.append(i); i+=1
        print(' ',motif,'positions',positions)
PY"}
